import type { Metadata } from "next";
import { siteConfig } from "@/lib/site-config";

type OgImage = { url: string; width: number; height: number; alt: string };

/** The site-wide social image generated by `app/opengraph-image.tsx`. */
export const defaultOgImage: OgImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: siteConfig.title,
};

/** Social image for a docs page, served by `app/og/docs/[...slug]/route.tsx`. */
export function docsOgImage(slugs: string[], title: string): OgImage {
  return {
    ...defaultOgImage,
    url: ["/og/docs", ...slugs, "image.png"].join("/"),
    alt: `${title} — ${siteConfig.name} documentation`,
  };
}

/**
 * Page metadata with complete Open Graph and Twitter tags.
 *
 * Next.js merges metadata shallowly, so a page that sets only `title` and
 * `description` inherits the root layout's `openGraph` and `twitter` objects
 * verbatim — every shared link would show the homepage's title and URL. Build
 * page metadata through this helper so social cards always match the page.
 */
export function createMetadata({
  title,
  description,
  path,
  type = "website",
  image = defaultOgImage,
  markdownPath,
}: {
  /** Page title; omitted for the homepage so the root default applies. */
  title?: string;
  description: string;
  /** Canonical path, e.g. "/features". */
  path: string;
  type?: "website" | "article";
  image?: OgImage;
  /** A plain-Markdown copy of the page for AI tools, e.g. "/docs/backups.md". */
  markdownPath?: string;
}): Metadata {
  // "<title> — Fleetdock", unless the title already names the product or is
  // long enough that the suffix would push it past what search results show.
  const standalone = title !== undefined && (title.includes(siteConfig.name) || title.length > 50);
  const socialTitle = title ? (standalone ? title : `${title} — ${siteConfig.name}`) : siteConfig.title;

  return {
    ...(title ? { title: standalone ? { absolute: title } : title } : {}),
    description,
    alternates: {
      canonical: path,
      ...(markdownPath ? { types: { "text/markdown": markdownPath } } : {}),
    },
    openGraph: {
      type,
      locale: "en_US",
      siteName: siteConfig.name,
      url: path,
      title: socialTitle,
      description,
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [image],
    },
  };
}

/** The Markdown twin of a content page: "/docs" → "/docs.md", "/blog/x" → "/blog/x.md". */
export function markdownPath(url: string): string {
  return `${url}.md`;
}

/** Content sections with their own social images at /og/<section>/<slug>/image.png. */
export type ContentSection = "blog" | "guides" | "alternatives";

/** Social image for a blog post, guide or comparison. */
export function contentOgImage(section: ContentSection, slugs: string[], title: string): OgImage {
  return {
    ...defaultOgImage,
    url: ["/og", section, ...slugs, "image.png"].join("/"),
    alt: `${title} — ${siteConfig.name}`,
  };
}
